def _theme_toggle() -> str:
    return (
        '<button type="button" class="dockle-theme-toggle" '
        'data-dockle-theme-toggle aria-label="Color scheme: auto">'
        '<i data-lucide="sun-moon" aria-hidden="true"></i></button>'
    )


def _page_actions(content: str) -> str:
    return (
        '<div class="dockle-page-actions" aria-label="Page actions">'
        f"{content}</div>"
    )


def _insert_into_page_actions(
    document: str,
    markup: str,
) -> str | None:
    match = _PAGE_ACTIONS_START.search(document)
    if match is None:
        return None
    closing = document.casefold().find("</div>", match.end())
    if closing < 0:
        return None

    return f"{document[:closing]}{markup}{document[closing:]}"


def _inject_theme_toggle(
    document: str,
    html_file: Path,
    framework: str,
) -> str:
    if "data-dockle-theme-toggle" in document:
        return document

    toggle = _theme_toggle()
    page_actions = _insert_into_page_actions(
        document,
        toggle,
    )
    if page_actions is not None:
        return page_actions

    actions = _page_actions(toggle)
    for pattern in _PAGE_CONTENT_STARTS.get(framework, ()):
        match = pattern.search(document)
        if match is not None:
            return f"{document[:match.end()]}{actions}{document[match.end():]}"
    return _insert_after_body(document, actions, html_file)


def _ensure_footer(document: str, footer: str, html_file: Path) -> str:
    if "data-dockle-built-with" not in document:
        return _insert_before_body_end(document, footer, html_file)
    updated, replacements = _replace_element(
        document, _DOCKLE_FOOTER_START, "</footer>", footer, count=1
    )
    return updated if replacements else document


def _replace_element(
    document: str,
    start_pattern: re.Pattern[str],
    closing_tag: str,
    replacement: str,
    *,
    count: int = 0,
) -> tuple[str, int]:
    replacements = 0
    offset = 0
    closing_lower = closing_tag.lower()
    while not count or replacements < count:
        match = start_pattern.search(document, offset)
        if match is None:
            break
        closing = document.lower().find(closing_lower, match.end())
        if closing < 0:
            break
        end = closing + len(closing_tag)
        document = f"{document[:match.start()]}{replacement}{document[end:]}"
        offset = match.start() + len(replacement)
        replacements += 1
    return document, replacements


def _insert_before_head_end(
    document: str,
    markup: str,
    html_file: Path,
) -> str:
    match = _HEAD_END.search(document)
    if match is None:
        raise ThemeError(
            f"generated HTML has no closing head element: {html_file}"
        )
    return f"{document[:match.start()]}{markup}{document[match.start():]}"


def _insert_after_body(
    document: str,
    markup: str,
    html_file: Path,
) -> str:
    match = _BODY_START.search(document)
    if match is None:
        raise ThemeError(f"generated HTML has no body element: {html_file}")
    return f"{document[:match.end()]}{markup}{document[match.end():]}"


def _insert_before_body_end(
    document: str,
    markup: str,
    html_file: Path,
) -> str:
    match = _BODY_END.search(document)
    if match is None:
        raise ThemeError(f"generated HTML has no closing body element: {html_file}")
    return f"{document[:match.start()]}{markup}{document[match.start():]}"


def _relative(asset: Path, html_file: Path) -> str:
    return Path(os.path.relpath(asset, html_file.parent)).as_posix()


def _copy_logo(logo: Path | str | None, asset_dir: Path) -> Path | str | None:
    if logo is None:
        return None
    if isinstance(logo, str):
        return logo
    destination = asset_dir / f"logo{logo.suffix.lower()}"
    shutil.copyfile(logo, destination)
    return destination


def _copy_favicon(
    favicon: Path | str | None, asset_dir: Path
) -> Path | str | None:
    if favicon is None:
        return None
    if isinstance(favicon, str):
        return favicon
    destination = asset_dir / f"favicon{favicon.suffix.lower()}"
    shutil.copyfile(favicon, destination)
    return destination


def _asset_url(asset: Path | str, html_file: Path) -> str:
    if isinstance(asset, str):
        return asset
    return _relative(asset, html_file)


def _inject_favicon(
    document: str,
    html_file: Path,
    favicon_asset: Path | str | None,
) -> str:
    if favicon_asset is None:
        return document
    document = _remove_favicon_links(document)
    relative_favicon = _asset_url(favicon_asset, html_file)
    link = (
        f'<link rel="icon" href="{escape(relative_favicon)}" '
        "data-dockle-favicon>\n"
    )
    return _insert_before_head_end(document, link, html_file)


def _remove_favicon_links(document: str) -> str:
    """Remove existing icon link elements without regex backtracking."""

    folded = document.casefold()
    fragments: list[str] = []
    retained_from = 0
    search_from = 0
    while (start := folded.find("<link", search_from)) >= 0:
        name_end = start + len("<link")
        if name_end < len(document) and document[name_end] not in " />\t\r\n":
            search_from = name_end
            continue
        end = _find_tag_end(document, name_end)
        if end is None:
            break
        tag = document[start:end + 1]
        parser = _LinkRelationshipParser()
        parser.feed(tag)
        search_from = end + 1
        if not parser.has_icon_relationship:
            continue
        while search_from < len(document) and document[search_from].isspace():
            search_from += 1
        fragments.append(document[retained_from:start])
        retained_from = search_from
    fragments.append(document[retained_from:])
    return "".join(fragments)


def _find_tag_end(document: str, start: int) -> int | None:
    """Find a tag terminator while respecting quoted attribute values."""

    quote: str | None = None
    for index in range(start, len(document)):
        character = document[index]
        if quote is not None:
            if character == quote:
                quote = None
            continue
        if character in {'"', "'"}:
            quote = character
        elif character == ">":
            return index
    return None


def _build_search_documents(
    html_files: list[Path],
    output: Path,
    framework: str,
) -> list[dict[str, str]]:
    documents: list[dict[str, str]] = []
    for html_file in html_files:
        parser = _SearchDocumentParser(framework)
        parser.feed(html_file.read_text(encoding="utf-8"))
        text = " ".join(parser.content if parser.has_content else parser.body)
        title = " ".join(parser.heading or parser.title)
        title = title.split(" — ", 1)[0].split(" – ", 1)[0]
        if not title:
            title = html_file.stem.replace("-", " ").title()
        documents.append(
            {
                "location": html_file.relative_to(output).as_posix(),
                "title": title,
                "text": text[:4000],
            }
        )
    return documents


def _page_decorations(
    *,
    html_file: Path,
    output: Path,
    portal: Path | None,
    framework: str,
    project_name: str,
    project_version: str,
    target_title: str,
    logo_asset: Path | str | None,
) -> str:
    relative_index = _relative(
        output / "_dockle" / "search.json",
        html_file,
    )
    relative_root = _relative(output, html_file)
    logo_url = _asset_url(logo_asset, html_file) if logo_asset else ""
    search = f"""<form class="dockle-search dockle-universal-search"
       data-dockle-universal-search data-dockle-logo-url="{escape(logo_url)}"
       data-dockle-target-title="{escape(target_title)}"
       action="{_relative(output / _SEARCH_PAGE, html_file)}"
       method="get" role="search">
    <label class="visually-hidden" for="dockle-search-input">
      Search documentation
    </label>
    <input id="dockle-search-input" type="search" name="q" required
           placeholder="Search documentation" autocomplete="off"
           data-dockle-search="{relative_index}"
           data-dockle-root="{relative_root}">
    <button class="dockle-search-submit" type="submit" aria-label="Search documentation"
            title="Search documentation"><i data-lucide="search" aria-hidden="true"></i></button>
    <ul class="dockle-search-results"
        data-dockle-search-results="dockle-search-input"
        aria-live="polite" hidden></ul>
  </form>"""
    links = ""
    if project_name and framework in {"doxygen", "jsdoc", "rustdoc"}:
        brand_root = portal if portal is not None else output
        relative_portal = _relative(brand_root / _INDEX_FILE, html_file)
        version = (
            f"<span>{escape(project_version)}</span>"
            if project_version
            else ""
        )
        links += (
            f'<a class="dockle-compat-brand" href="{relative_portal}" '
            f"data-dockle-brand><strong>{escape(project_name)}</strong>"
            f"{version}</a>"
        )
    return f'{links}<div class="dockle-toolbar">{search}</div>'


def _framework_version(framework: str, html_files: list[Path]) -> str:
    if framework == "jsdoc":
        jsdoc_version = _jsdoc_version(html_files)
        if jsdoc_version:
            return jsdoc_version
    pattern = _FRAMEWORK_VERSION_PATTERNS.get(framework)
    if pattern is not None:
        for html_file in html_files:
            match = pattern.search(html_file.read_text(encoding="utf-8"))
            if match is not None:
                return match.group(1).strip()
    distribution = _FRAMEWORK_DISTRIBUTIONS.get(framework)
    if distribution is None:
        return ""
    try:
        return version(distribution)
    except PackageNotFoundError:
        return ""


def _jsdoc_version(html_files: list[Path]) -> str:
    marker = "jsdoc "
    closing_tag = "</a>"
    for html_file in html_files:
        document = html_file.read_text(encoding="utf-8")
        lowered = document.lower()
        start = lowered.find(marker)
        if start < 0:
            continue
        start += len(marker)
        end = lowered.find(closing_tag, start)
        if end >= 0:
            return document[start:end].strip()
    return ""


def _built_with_footer(framework: str = "", framework_version: str = "") -> str:
    framework_name, framework_url = _FRAMEWORKS.get(
        framework,
        (framework, ""),
    )
    framework_attribution = ""
    if framework_name:
        label = escape(framework_name)
        if framework_version:
            label += f" {escape(framework_version)}"
        if framework_url:
            label = (
                f'<a href="{framework_url}">{label}'
                '<i data-lucide="external-link" aria-hidden="true"></i></a>'
            )
        framework_attribution = f" with {label}"
    return (
        '<footer class="dockle-footer dockle-built-with" '
        'data-dockle-built-with>'
        f'Generated by <a href="{_DOCKLE_URL}">Dockle {__version__}'
        '<i data-lucide="external-link" aria-hidden="true"></i>'
        f'</a>{framework_attribution}.</footer>'
    )


def write_portal(
    config: DockleConfig,
    targets: tuple[TargetConfig, ...],
    stylesheet: str,
) -> Path:
    """Write the root project documentation and comparison cards."""

    output = config.build.output
    output.mkdir(parents=True, exist_ok=True)
    home_target = next((target for target in config.targets if target.home), None)
    card_targets = _portal_card_targets(config, targets, home_target)
    cards = _portal_cards(card_targets, output)
    portal = _portal_path(config)
    if home_target is not None and portal.is_file():
        return _update_home_portal(config, cards, bool(card_targets))

    asset_dir = _write_theme_assets(output, stylesheet)
    logo_asset = _copy_logo(config.project.logo, asset_dir)
    favicon_asset = _copy_favicon(config.project.favicon, asset_dir)
    document = _standalone_portal_document(
        config,
        cards,
        logo_asset,
        favicon_asset,
    )
    portal.write_text(document, encoding="utf-8")
    return portal


def write_home_aliases(config: DockleConfig) -> int:
    """Preserve target-prefixed links after publishing a target at the root."""

    home_target = next((target for target in config.targets if target.home), None)
    if home_target is None:
        return 0

    output = config.build.output.resolve()
    alias_root = (output / home_target.name).resolve()
    if alias_root.parent != output:
        raise ThemeError(f"home alias must stay within build output: {alias_root}")
    conflicts = tuple(
        target
        for target in config.targets
        if target is not home_target
        and (
            target.output == alias_root
            or target.output.is_relative_to(alias_root)
            or alias_root.is_relative_to(target.output)
        )
    )
    if conflicts:
        names = ", ".join(target.name for target in conflicts)
        raise ThemeError(f"home alias conflicts with target output: {names}")

    html_files = tuple(
        path.resolve()
        for path in output.rglob(_HTML_GLOB)
        if not path.is_symlink()
        and not path.resolve().is_relative_to(alias_root)
    )
    aliases = 0
    for html_file in html_files:
        relative = html_file.relative_to(output)
        destinations = [alias_root / relative]
        if relative.name != _INDEX_FILE:
            destinations.append(
                alias_root / relative.with_suffix("") / _INDEX_FILE
            )
        for destination in destinations:
            destination.parent.mkdir(parents=True, exist_ok=True)
            target = _relative(html_file, destination)
            destination.write_text(
                _redirect_document(target), encoding="utf-8"
            )
            aliases += 1
    return aliases


def _redirect_document(target: str) -> str:
    escaped_target = escape(target, quote=True)
    script_target = json.dumps(target)
    return f"""<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="robots" content="noindex">
  <meta http-equiv="refresh" content="0; url={escaped_target}">
  <link rel="canonical" href="{escaped_target}">
  <title>Documentation moved</title>
</head>
<body>
  <p>This documentation moved to <a href="{escaped_target}">{escaped_target}</a>.</p>
  <script>location.replace(new URL({script_target}, document.baseURI).href + location.search + location.hash);</script>
</body>
</html>
"""


def _portal_path(config: DockleConfig) -> Path:
    """Return the fixed portal file after validating the configured output."""

    root = config.root.resolve()
    output = config.build.output.resolve()
    if output != root and not output.is_relative_to(root):
        raise ThemeError(f"build output must stay within project root: {output}")
    portal = (output / _INDEX_FILE).resolve()
    if portal.parent != output:
        raise ThemeError(f"portal path must stay within build output: {portal}")
    return portal


def _portal_card_targets(
    config: DockleConfig,
    targets: tuple[TargetConfig, ...],
    home_target: TargetConfig | None,
) -> tuple[TargetConfig, ...]:
    candidates = config.targets if home_target is not None else targets
    return tuple(
        target for target in candidates if not target.home and target.publish
    )


def _update_home_portal(
    config: DockleConfig, cards: str, has_cards: bool
) -> Path:
    output = config.build.output.resolve()
    portals = [
        candidate.resolve()
        for candidate in output.glob(_INDEX_FILE)
        if not candidate.is_symlink()
    ]
    if len(portals) != 1 or portals[0].parent != output:
        raise ThemeError(f"home target has no safe portal file in {output}")
    portal = portals[0]
    if not has_cards:
        return portal
    document = portal.read_text(encoding="utf-8")
    cards_markup = (
        '<div data-dockle-target-cards class="dockle-portal-grid" '
        'aria-label="Documentation examples">\n'
        f"{cards}\n"
        "</div>"
    )
    document, replacements = _replace_element(
        document,
        _TARGET_CARDS_START,
        "</div>",
        cards_markup,
        count=1,
    )
    if not replacements:
        heading = _FIRST_H1_END.search(document)
        if heading is None:
            raise ThemeError(
                f"home target has no heading for comparison cards: {portal}"
            )
        document = (
            f"{document[:heading.end()]}\n{cards_markup}"
            f"{document[heading.end():]}"
        )
    portal.write_text(document, encoding="utf-8")
    return portal


def _standalone_portal_document(
    config: DockleConfig,
    cards: str,
    logo_asset: Path | str | None,
    favicon_asset: Path | str | None,
) -> str:
    version = _portal_version(config.project.version)
    repository = _portal_repository(config.project.repository)
    logo = _portal_logo(logo_asset)
    favicon = _portal_favicon(favicon_asset)
    project_docs = _portal_project_docs(config.project.home)
    return f"""<!doctype html>
<html lang="en" data-dockle-framework="portal">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width, initial-scale=1">
  <meta name="description" content="{escape(config.project.description)}">
  <title>{escape(config.project.name)} documentation</title>
{favicon}  <link rel="stylesheet" href="_dockle/dockle.css" data-dockle-theme="portal">
  <script defer src="_dockle/lucide.min.js" data-dockle-lucide></script>
  <script defer src="_dockle/highlight.min.js" data-dockle-highlight></script>
  <script defer src="_dockle/dockle.js" data-dockle-script></script>
</head>
<body class="dockle-portal">
  <main>
    <header>
{logo}      <div>
        <p class="dockle-portal-kicker">Documentation</p>
        <h1>{escape(config.project.name)}{version}</h1>
        <p>{escape(config.project.description)}</p>
      </div>
    </header>
    <section class="dockle-portal-grid" aria-label="Documentation examples">
{cards}
    </section>
{project_docs}{repository}    <footer class="dockle-footer dockle-built-with dockle-portal-built-with"
          data-dockle-built-with>
    Generated by <a href="{_DOCKLE_URL}">Dockle {__version__}<i
      data-lucide="external-link" aria-hidden="true"></i></a>.
    </footer>
  </main>
  <button type="button" class="dockle-theme-toggle"
          data-dockle-theme-toggle aria-label="Color scheme: auto">
    <i data-lucide="sun-moon" aria-hidden="true"></i>
  </button>
</body>
</html>
"""


def _portal_version(version: str) -> str:
    return f" <span>{escape(version)}</span>" if version else ""


def _portal_repository(repository: str) -> str:
    if not repository:
        return ""
    return (
        '    <p class="dockle-portal-repository">'
        f'<a href="{escape(repository)}">Source repository'
        '<i data-lucide="external-link" aria-hidden="true"></i>'
        "</a></p>\n"
    )


def _portal_logo(asset: Path | str | None) -> str:
    if asset is None:
        return ""
    return (
        '      <img class="dockle-portal-logo" '
        f'src="{escape(_portal_asset_url(asset))}" alt="">\n'
    )


def _portal_favicon(asset: Path | str | None) -> str:
    if asset is None:
        return ""
    return (
        f'  <link rel="icon" href="{escape(_portal_asset_url(asset))}" '
        "data-dockle-favicon>\n"
    )


def _portal_asset_url(asset: Path | str) -> str:
    return asset if isinstance(asset, str) else f"_dockle/{asset.name}"


def _portal_project_docs(home: Path | None) -> str:
    if home is None:
        return ""
    source = home.read_text(encoding="utf-8")
    return (
        '    <article class="dockle-portal-docs">\n'
        f"{render_markdown(source)}\n"
        "    </article>\n"
    )


def _portal_cards(
    targets: tuple[TargetConfig, ...], output: Path
) -> str:
    """Render the shared comparison cards for portal or Sphinx home pages."""

    cards: list[str] = []
    for target in targets:
        relative = _target_href(target, output)
        description = target.description or (
            f"Documentation generated with {target.framework}."
        )
        cards.append(
            f"""      <a class="dockle-portal-card" href="{escape(relative)}">
        <span class="dockle-portal-framework">{escape(target.framework)}</span>
        <strong>{escape(target.title)}</strong>
        <span>{escape(description)}</span>
      </a>"""
        )
    return "\n".join(cards)


def _target_href(target: TargetConfig, output: Path) -> str:
    relative = target.output.relative_to(output).as_posix()
    if target.framework == "rustdoc" and target.output.is_dir():
        crates = sorted(
            path
            for path in target.output.iterdir()
            if path.is_dir() and (path / _INDEX_FILE).is_file()
        )
        if len(crates) == 1:
            return f"{relative}/{crates[0].name}/"
    return f"{relative}/"
